import json,sys
sys.path.insert(0,sys.argv[1]+'/backend')
from services.contract_scout import scout_candidates
from datetime import datetime,UTC
now=datetime(2030,1,2,14,tzinfo=UTC).timestamp()
c={'osi':'TEST','type':'put','strike':500,'expiry':'2030-01-02','bid':1.,'ask':1.2,'delta':-.5,'gamma':.05,'volume':500.,'T':.5/365,'bid_timestamp':'2030-01-02T14:00:00+00:00','ask_timestamp':'2030-01-02T14:00:00+00:00'}
out={}
for name,over in [('control',{}),('volume_nan',{'volume':float('nan')}),('T_nan',{'T':float('nan')}),('T_infinity',{'T':float('inf')}),('unknown_contract_type',{'type':'unknown'}),('future_bid_ask',{'bid_timestamp':'2030-01-03T14:00:00+00:00','ask_timestamp':'2030-01-03T14:00:00+00:00'})]:
